export async function replaceProductMeasurements(
  productId: string,
  companyId: string,
  measurementIds: string[],
) {
  const { error: deleteError } = await supabase
    .from("product_measurements")
    .delete()
    .eq("product_id", productId);
  if (deleteError) throw deleteError;

  if (measurementIds.length === 0) return;
  const { error } = await supabase.from("product_measurements").insert(
    measurementIds.map((measurementId, index) => ({
      product_id: productId,
      measurement_id: measurementId,
      sort_order: index,
    })),
  );
  if (error) throw error;
  void companyId;
}

export async function listProductMeasurements(productId: string, companyId: string) {
  const { data, error } = await supabase
    .from("product_measurements")
    .select(
      "measurement_id, sort_order, company_measurements(id, company_id, label, sort_order, is_active, created_at, updated_at)",
    )
    .eq("product_id", productId)
    .eq("company_measurements.company_id", companyId)
    .order("sort_order", { ascending: true });
  if (error) throw error;
  return (data ?? []).map((row) => ({
    measurement_id: row.measurement_id,
    sort_order: row.sort_order,
    measurement: row.company_measurements as unknown as CompanyMeasurement,
  }));
}
